import express from 'express';
import cors from 'cors';
import { Client } from 'ssh2';

const app = express();
app.use(cors());
app.use(express.json());

let globalSshConfig = null;

const execSSH = (command) => {
  return new Promise((resolve, reject) => {
    if (!globalSshConfig) return reject(new Error('Not connected. Login first.'));
    const conn = new Client();
    conn.on('ready', () => {
      conn.exec(command, (err, stream) => {
        if (err) { conn.end(); return reject(err); }
        let stdout = ''; let stderr = '';
        stream.on('close', (code, signal) => {
          conn.end(); resolve({ stdout, stderr, code });
        }).on('data', (data) => stdout += data.toString())
          .stderr.on('data', (data) => stderr += data.toString());
      });
    }).on('error', (err) => reject(err)).connect(globalSshConfig);
  });
};

app.get('/api/status', (req, res) => {
  if (globalSshConfig) {
    res.json({ connected: true, host: globalSshConfig.host });
  } else {
    res.json({ connected: false });
  }
});

app.post('/api/logout', (req, res) => {
  globalSshConfig = null;
  res.json({ success: true });
});

app.post('/api/connect', async (req, res) => {
  const { host, port, username, password } = req.body;
  try {
    const config = { host, port: parseInt(port || '22'), username, password, readyTimeout: 10000 };
    const conn = new Client();
    await new Promise((resolve, reject) => {
      conn.on('ready', () => { conn.end(); resolve(); }).on('error', (err) => reject(err)).connect(config);
    });
    globalSshConfig = config;
    res.json({ success: true, message: 'Connected successfully!' });
  } catch (err) { res.status(401).json({ success: false, error: err.message }); }
});

app.get('/api/scan', async (req, res) => {
  try {
    const result = await execSSH('pm2 jlist');
    let pm2Apps = [];
    try { pm2Apps = JSON.parse(result.stdout); } catch(e) {}
    const projects = pm2Apps.map(app => ({
      name: app.name,
      pid: app.pid,
      status: app.pm2_env.status,
      memory: Math.round(app.monit.memory / 1024 / 1024) + ' MB',
      cpu: app.monit.cpu + '%',
      path: app.pm2_env.pm_cwd
    }));
    res.json({ success: true, projects });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

app.post('/api/project-files', async (req, res) => {
  const { projectPath, portOrName } = req.body;
  try {
    let files = [];
    const cmdEnv = 'ls -l ' + projectPath + '/.env || echo "NOT_FOUND"';
    const envCheck = await execSSH(cmdEnv);
    if (!envCheck.stdout.includes('NOT_FOUND')) files.push({ name: '.env', path: projectPath + '/.env', type: 'env' });

    const cmdPkg = 'ls -l ' + projectPath + '/package.json || echo "NOT_FOUND"';
    const pkgCheck = await execSSH(cmdPkg);
    if (!pkgCheck.stdout.includes('NOT_FOUND')) files.push({ name: 'package.json', path: projectPath + '/package.json', type: 'config' });

    const cmdNginx = 'grep -Rl "' + projectPath + '" /etc/nginx/sites-available/ || echo "NOT_FOUND"';
    const nginxCheck = await execSSH(cmdNginx);
    if (!nginxCheck.stdout.includes('NOT_FOUND')) {
      const nginxFiles = nginxCheck.stdout.split('\n').filter(f => f.trim() !== '');
      nginxFiles.forEach(f => {
        if(f !== 'NOT_FOUND') files.push({ name: f.split('/').pop() + ' (Nginx)', path: f, type: 'nginx' });
      });
    }
    res.json({ success: true, files });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

app.post('/api/read-file', async (req, res) => {
  const { path } = req.body;
  const conn = new Client();
  conn.on('ready', () => {
    conn.sftp((err, sftp) => {
      if (err) { conn.end(); return res.status(500).json({ error: err.message }); }
      sftp.readFile(path, 'utf8', (err, data) => {
        conn.end();
        if (err) return res.status(500).json({ error: err.message });
        res.json({ data });
      });
    });
  }).on('error', (err) => res.status(500).json({ error: err.message })).connect(globalSshConfig);
});

// Route SFTP Tulis File
app.post('/api/write-file', async (req, res) => {
  const { path, content } = req.body;
  const conn = new Client();
  conn.on('ready', () => {
    conn.sftp((err, sftp) => {
      if (err) { conn.end(); return res.status(500).json({ error: err.message }); }
      sftp.writeFile(path, content, 'utf8', (err) => {
        conn.end();
        if (err) return res.status(500).json({ error: err.message });
        res.json({ success: true });
      });
    });
  }).on('error', (err) => res.status(500).json({ error: err.message })).connect(globalSshConfig);
});

const PORT = 3001;
app.listen(PORT, () => console.log('Backend running on ' + PORT));

import React, { useState, useEffect } from 'react';
import { Terminal, Server, FileCode, Play, LogOut, Loader2, CheckCircle2, AlertCircle, Folder, Settings, ShieldCheck, RefreshCw } from 'lucide-react';
import './index.css';

function App() {
  const [step, setStep] = useState(0); 
  const [creds, setCreds] = useState({ host: '', port: '22', username: 'root', password: '' });
  const [rememberMe, setRememberMe] = useState(false);
  const [status, setStatus] = useState('');

  const [projects, setProjects] = useState([]);
  const [selectedProject, setSelectedProject] = useState(null);
  const [files, setFiles] = useState([]);

  const [fileContent, setFileContent] = useState('');
  const [currentFile, setCurrentFile] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => { checkConnection(); }, []);

  const checkConnection = async () => {
    try {
      const res = await fetch('http://localhost:3001/api/status');
      const data = await res.json();
      if (data.connected) {
        setCreds({ ...creds, host: data.host });
        setStep(2); scanProjects();
      } else {
        const savedCreds = localStorage.getItem('neo_vps_creds');
        if (savedCreds) {
          const parsed = JSON.parse(savedCreds);
          setCreds(parsed); setRememberMe(true); autoLogin(parsed);
        } else setStep(1);
      }
    } catch (e) {
      const savedCreds = localStorage.getItem('neo_vps_creds');
      if (savedCreds) { setCreds(JSON.parse(savedCreds)); setRememberMe(true); }
      setStep(1);
    }
  };

  const autoLogin = async (credentials) => {
    setIsLoading(true); setStatus('Auto-connecting to VPS...');
    try {
      const res = await fetch('http://localhost:3001/api/connect', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(credentials)
      });
      const data = await res.json();
      if (data.success) { setStep(2); scanProjects(); } 
      else { setStatus('Auto-login gagal: ' + data.error); setStep(1); }
    } catch (err) { setStatus('Error koneksi: ' + err.message); setStep(1); }
    setIsLoading(false);
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setIsLoading(true); setStatus('Menghubungkan via SSH...');
    try {
      const res = await fetch('http://localhost:3001/api/connect', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(creds)
      });
      const data = await res.json();
      if (data.success) {
        if (rememberMe) localStorage.setItem('neo_vps_creds', JSON.stringify(creds));
        else localStorage.removeItem('neo_vps_creds');
        setStep(2); scanProjects(); setStatus('');
      } else setStatus('Gagal: ' + data.error);
    } catch (err) { setStatus('Error koneksi lokal: ' + err.message); }
    setIsLoading(false);
  };

  const handleLogout = async () => {
    await fetch('http://localhost:3001/api/logout', { method: 'POST' });
    localStorage.removeItem('neo_vps_creds');
    setCreds({ host: '', port: '22', username: 'root', password: '' });
    setRememberMe(false); setStep(1); setProjects([]); setFiles([]);
    setCurrentFile(''); setFileContent(''); setStatus('');
  };

  const scanProjects = async () => {
    setStatus('Mendeteksi project PM2...'); setIsLoading(true);
    const res = await fetch('http://localhost:3001/api/scan');
    const data = await res.json();
    if (data.success) { setProjects(data.projects); setStatus(''); }
    setIsLoading(false);
  };

  const handleSelectProject = async (proj) => {
    setSelectedProject(proj); setFiles([]); setFileContent(''); setCurrentFile('');
    setStatus('Mencari file konfigurasi...'); setIsLoading(true);
    const res = await fetch('http://localhost:3001/api/project-files', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ projectPath: proj.path, portOrName: proj.name })
    });
    const data = await res.json();
    if (data.success) { setFiles(data.files); setStatus(''); }
    setIsLoading(false);
  };

  const openFile = async (file) => {
    setStatus('Membaca file...'); setIsLoading(true);
    const res = await fetch('http://localhost:3001/api/read-file', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ path: file.path })
    });
    const data = await res.json();
    if (data.data !== undefined) {
      setFileContent(data.data); setCurrentFile(file.path); setStatus('');
    } else setStatus('Gagal: ' + data.error);
    setIsLoading(false);
  };

  const saveFile = async () => {
    setIsSaving(true); setStatus('Menyimpan ke server...');
    const res = await fetch('http://localhost:3001/api/write-file', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ path: currentFile, content: fileContent })
    });
    const data = await res.json();
    if (data.success) { setStatus('Tersimpan!'); setTimeout(() => setStatus(''), 2000); }
    else setStatus('Gagal: ' + data.error);
    setIsSaving(false);
  };

  if (step === 0) return (
    <div className="flex h-screen w-full items-center justify-center bg-slate-900 text-slate-300">
      <div className="flex flex-col items-center gap-4">
        <Loader2 className="w-8 h-8 animate-spin text-blue-500" />
        <p>Memuat sesi keamanan...</p>
      </div>
    </div>
  );

  if (step === 1) {
    return (
      <div className="flex h-screen w-full items-center justify-center bg-slate-900">
        <div className="w-full max-w-md bg-slate-800 rounded-2xl shadow-2xl p-8 border border-slate-700">
          <div className="flex items-center gap-3 mb-8">
            <div className="w-10 h-10 rounded-lg bg-blue-500/20 flex items-center justify-center">
              <Server className="w-6 h-6 text-blue-400" />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-white">Neo-Panel</h2>
              <p className="text-slate-400 text-sm">Masuk ke Remote VPS Anda</p>
            </div>
          </div>

          <form onSubmit={handleLogin} className="flex flex-col gap-5">
            <div className="flex gap-4">
              <div className="flex-1">
                <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 block">IP Address</label>
                <input className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-blue-500 outline-none transition" placeholder="103.x.x.x" value={creds.host} onChange={e => setCreds({...creds, host: e.target.value})} required />
              </div>
              <div className="w-24">
                <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 block">Port</label>
                <input className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-blue-500 outline-none transition" placeholder="22" value={creds.port} onChange={e => setCreds({...creds, port: e.target.value})} required />
              </div>
            </div>

            <div>
              <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 block">Username</label>
              <input className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-blue-500 outline-none transition" value={creds.username} onChange={e => setCreds({...creds, username: e.target.value})} required />
            </div>

            <div>
              <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 block">Password</label>
              <input type="password" className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-blue-500 outline-none transition" value={creds.password} onChange={e => setCreds({...creds, password: e.target.value})} required />
            </div>

            <label className="flex items-center gap-3 cursor-pointer mt-2 group">
              <input type="checkbox" className="w-5 h-5 rounded border-slate-600 bg-slate-900 text-blue-500 focus:ring-blue-500/50" checked={rememberMe} onChange={e => setRememberMe(e.target.checked)} />
              <span className="text-sm text-slate-300 group-hover:text-white transition">Simpan Kredensial untuk Auto-Login</span>
            </label>

            <button type="submit" disabled={isLoading} className="mt-4 bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 px-4 rounded-lg flex items-center justify-center gap-2 transition disabled:opacity-50">
              {isLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : <ShieldCheck className="w-5 h-5" />}
              {isLoading ? 'Menghubungkan...' : 'Connect to VPS'}
            </button>
          </form>
          {status && <div className="mt-6 p-3 bg-red-500/10 border border-red-500/20 text-red-400 rounded-lg text-sm flex items-center gap-2"><AlertCircle className="w-4 h-4"/>{status}</div>}
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-slate-900 font-sans text-slate-200 overflow-hidden">
      {/* SIDEBAR */}
      <div className="w-80 bg-slate-950 border-r border-slate-800 flex flex-col">
        <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-900/50">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded bg-blue-500/20 flex items-center justify-center">
              <Server className="w-4 h-4 text-blue-400" />
            </div>
            <div>
              <h3 className="font-bold text-white tracking-wide">Neo-Panel</h3>
              <p className="text-[10px] text-slate-400 uppercase tracking-widest">{creds.host}</p>
            </div>
          </div>
          <button onClick={handleLogout} className="p-2 rounded hover:bg-red-500/20 text-slate-400 hover:text-red-400 transition" title="Logout">
            <LogOut className="w-4 h-4" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          <div className="flex items-center justify-between mb-4 mt-2">
            <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
              <Terminal className="w-4 h-4" /> PM2 Workspaces
            </h4>
            <button onClick={scanProjects} className="text-slate-500 hover:text-blue-400 transition"><RefreshCw className="w-4 h-4" /></button>
          </div>

          <div className="flex flex-col gap-2">
            {projects.length === 0 && !isLoading && <div className="text-sm text-slate-600 italic">No apps running in PM2</div>}
            {projects.map(p => (
              <div 
                key={p.name} onClick={() => handleSelectProject(p)}
                className={`p-3 rounded-xl border cursor-pointer transition-all duration-200 ${selectedProject?.name === p.name ? 'border-blue-500 bg-blue-500/10' : 'border-slate-800 hover:bg-slate-800'}`}
              >
                <div className="flex items-center justify-between mb-1">
                  <strong className="font-semibold text-slate-200">{p.name}</strong>
                  <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium ${p.status === 'online' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
                    {p.status}
                  </span>
                </div>
                <div className="flex gap-4 text-xs text-slate-500 mt-2">
                  <span className="flex items-center gap-1">RAM: {p.memory}</span>
                  <span className="flex items-center gap-1">CPU: {p.cpu}</span>
                </div>
              </div>
            ))}
          </div>

          {selectedProject && (
            <div className="mt-8 animate-in fade-in slide-in-from-left-2 duration-300">
              <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-4">
                <Folder className="w-4 h-4" /> Configuration Files
              </h4>
              <div className="flex flex-col gap-1">
                {isLoading && !currentFile && <div className="flex items-center gap-2 text-sm text-slate-500"><Loader2 className="w-4 h-4 animate-spin"/> Scanning...</div>}
                {files.map(f => (
                  <div 
                    key={f.path} onClick={() => openFile(f)}
                    className={`flex items-center gap-3 p-2.5 rounded-lg cursor-pointer transition ${currentFile === f.path ? 'bg-blue-500/10 text-blue-400' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`}
                  >
                    {f.type === 'env' ? <Settings className="w-4 h-4" /> : <FileCode className="w-4 h-4" />}
                    <span className="text-sm font-medium">{f.name}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* EDITOR AREA */}
      <div className="flex-1 flex flex-col bg-[#0f172a]">
        {/* Header */}
        <div className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/80 backdrop-blur">
          <div className="flex items-center gap-2 text-slate-400 text-sm">
            {currentFile ? (
              <>
                <FileCode className="w-4 h-4 text-blue-400" />
                <span className="font-mono text-slate-300">{currentFile}</span>
              </>
            ) : (
              <span>Pilih file dari sidebar</span>
            )}
          </div>

          <div className="flex items-center gap-4">
            {status && (
              <span className="text-sm font-medium text-emerald-400 animate-pulse">{status}</span>
            )}
            <button 
              onClick={saveFile} 
              disabled={!currentFile || isSaving}
              className="bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-medium py-2 px-5 rounded-md flex items-center gap-2 transition"
            >
              {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <ShieldCheck className="w-4 h-4" />}
              {isSaving ? 'Menyimpan...' : 'Save Configuration'}
            </button>
          </div>
        </div>

        {/* Editor Content */}
        <div className="flex-1 p-6 relative">
          {currentFile ? (
            <textarea 
              value={fileContent} 
              onChange={e => setFileContent(e.target.value)}
              spellCheck="false"
              className="w-full h-full bg-[#1e293b]/50 border border-slate-700/50 rounded-xl text-slate-300 font-mono text-sm p-6 focus:outline-none focus:border-blue-500/50 focus:ring-1 focus:ring-blue-500/50 transition resize-none custom-scrollbar shadow-inner"
              style={{ lineHeight: '1.6' }}
            />
          ) : (
            <div className="w-full h-full flex flex-col items-center justify-center text-slate-600">
              <Server className="w-20 h-20 mb-6 opacity-20" />
              <h2 className="text-2xl font-bold text-slate-500 mb-2">Welcome to Neo-Panel</h2>
              <p className="max-w-md text-center text-sm">Pilih Workspace PM2 di sebelah kiri, lalu buka file konfigurasi (.env atau Nginx) untuk mulai mengelola infrastruktur Anda secara visual.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default App;
